-:root{--pink:#ff3b8d;--cyan:#5af5ed;--gold:#ffdf72;--ink:#100d18}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#100d18;color:#f5edf7;font-family:'Barlow Condensed',Arial,sans-serif}body{display:grid;place-items:center}.shell{position:relative;width:min(100vw,160vh);height:min(100vh,62.5vw);max-width:1280px;max-height:800px;background:#11101c;overflow:hidden;border:1px solid #39253d;box-shadow:0 0 70px #08070d}canvas{width:100%;height:100%;display:block;image-rendering:pixelated}.scanlines,.vignette{position:absolute;inset:0;pointer-events:none}.scanlines{opacity:.13;background:repeating-linear-gradient(0deg,transparent 0 3px,#000 4px 5px)}.vignette{background:radial-gradient(ellipse at center,transparent 52%,#090711b8 100%)}.screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(120deg,#0d0b16df,#17101bd9 55%,#0d0b16e8);padding:24px}.panel{width:min(620px,96%);border:1px solid #f548886b;background:#130f1beF;box-shadow:0 0 0 5px #ff3b8d12,0 20px 70px #000b;padding:clamp(20px,4vw,42px);position:relative}.panel:before,.panel:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--cyan);border-style:solid}.panel:before{top:-1px;left:-1px;border-width:2px 0 0 2px}.panel:after{right:-1px;bottom:-1px;border-width:0 2px 2px 0}.eyebrow,.mono{font-family:'Share Tech Mono',monospace;text-transform:uppercase;letter-spacing:.13em}.eyebrow{font-size:12px;color:var(--cyan)}h1{font-size:clamp(52px,10vw,94px);line-height:.8;letter-spacing:-.03em;margin:16px 0 12px;font-weight:900;text-transform:uppercase;color:#fff;text-shadow:4px 4px 0 #ff3b8d,8px 8px 0 #5af5ed55}h1 span{color:var(--pink)}.subtitle{font-size:20px;letter-spacing:.06em;text-transform:uppercase;color:#c6b8cf}.rule{height:1px;background:linear-gradient(90deg,var(--pink),#654065,transparent);margin:22px 0}.story{font-size:16px;line-height:1.45;color:#d2c8d7;max-width:500px}.controls{display:grid;grid-template-column